<script lang="ts">
 import {interfaceLanguage} from '$lib/i18n/context.svelte';const ui=interfaceLanguage();import Page from '$lib/components/PlatformPage.svelte';import {request} from '$lib/platform/client';let current=$state(''),password=$state(''),message=$state(''),busy=$state(false);async function save(e:SubmitEvent){e.preventDefault();busy=true;try{await request('/api/auth/password',{current,password});current='';password='';message='Contraseña actualizada. Las otras sesiones se han cerrado.';}catch(e){message=(e as Error).message;}finally{busy=false;}}</script>
<Page title={ui.text("Mi cuenta")}><section><form onsubmit={save}><label>{ui.text("Contraseña actual")}<input required type="password" autocomplete="current-password" bind:value={current}/></label><label>{ui.text("Nueva contraseña · mínimo 10 caracteres")}<input required minlength="10" type="password" autocomplete="new-password" bind:value={password}/></label><button disabled={busy}>{ui.text("Cambiar contraseña")}</button></form>{#if message}<p role="status">{ui.text(message)}</p>{/if}</section></Page>
